package com.markethub.order;
import com.markethub.vendor.Vendor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class VendorOrderItemStatusService {private final VendorOrderService vendorService;private final VendorOrderRepository orders;private final VendorOrderItemRepository items;public VendorOrderItemStatusService(VendorOrderService v,VendorOrderRepository o,VendorOrderItemRepository i){vendorService=v;orders=o;items=i;}
 @Transactional public VendorOrderItemResponse update(String email,Long orderId,Long itemId,VendorOrderItemStatusRequest request){Vendor v=vendorService.vendor(email);Order o=orders.findById(orderId).orElseThrow(OrderNotFoundException::new);OrderItem item=items.findById(itemId).orElseThrow(OrderNotFoundException::new);if(!item.getOrder().getId().equals(orderId)||!item.getVendorId().equals(v.getId()))throw new OrderNotFoundException();if(o.getStatus()==OrderStatus.CANCELLED)throw new CheckoutConflictException("Cancelled orders cannot be processed");if(!valid(item.getStatus(),request.status()))throw new CheckoutConflictException("Invalid order item status transition");item.setStatus(request.status());return VendorOrderItemResponse.from(items.saveAndFlush(item));}
 private boolean valid(OrderStatus from,OrderStatus to){return (from==OrderStatus.PENDING&&to==OrderStatus.CONFIRMED)||(from==OrderStatus.CONFIRMED&&to==OrderStatus.PROCESSING)||(from==OrderStatus.PROCESSING&&to==OrderStatus.SHIPPED)||(from==OrderStatus.SHIPPED&&to==OrderStatus.DELIVERED);}
}
